def selected_model(grid):
 h,w=len(grid),len(grid[0]); clues=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
 for n in range(1,max(h,w)+1):
  candidates=[]
  for a in range(n):
   for b in range(n):
    vals={}; ok=True
    for r,c,v in clues:
     k=(a*r+b*c)%n
     if k in vals and vals[k]!=v:ok=False;break
     vals[k]=v
    if ok: candidates.append((n,len(vals),a,b,vals))
  if candidates:
   candidates.sort(key=lambda z:(-z[1], (z[2]==0)+(z[3]==0), z[2]+z[3],z[2],z[3]))
   return candidates[0]
